add('The interface could not load: ','No se pudo cargar la interfaz: |Impossible de charger l’interface : |Die Oberfläche konnte nicht geladen werden: |Não foi possível carregar a interface: |Impossibile caricare l’interfaccia: |De interface kon niet worden geladen: |Nie udało się wczytać interfejsu: ')
add('Startup log: ','Registro de inicio: |Journal de démarrage : |Startprotokoll: |Registo de arranque: |Registro di avvio: |Opstartlogboek: |Dziennik uruchamiania: ')
sources=json.loads((ROOT/'locales/sources.json').read_text(encoding='utf-8'))
for key in M:sources.setdefault(key,['desktop/Program.cs'])
(ROOT/'locales/sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for code in ('en',*LANGS):
    path=ROOT/'locales'/f'{code}.json';data=json.loads(path.read_text(encoding='utf-8'))
    for key in M:data['messages'][key]=key if code=='en' else M[key][LANGS.index(code)]
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
